struct mm_struct *init_mm(struct mm_struct *mm, struct task_struct *p, struct user_namespace *user_ns) {
    int ret = 0;

    if (!mm || !p || !user_ns) {
        return NULL;
    }

    mm->mmap = NULL;
    mm->mmap_next = NULL;
    mm->mmap_read_lock = (spinlock_t)SPIN_LOCK_INITIALIZER;
    mm->mmap_write_lock = (spinlock_t)SPIN_LOCK_INITIALIZER;
    atomic_set(&mm->mm_users, 1);
    atomic_set(&mm->mm_count, 1);
    mm->flags = 0;

    ret = setup_new_context(mm, user_ns);
    if (ret) {
        return NULL;
    }

    ret = allocate_page_tables(mm);
    if (ret) {
        teardown_context(mm);
        return NULL;
    }

    return mm;
}
